  values ('ME', 'short_answer', 'List the 6 building blocks of health systems. Describe one of them in 2-3 lines. (2+1 marks)', 'The WHO six building blocks of a health system are: (1) service delivery; (2) health workforce; (3) health information systems; (4) access to essential medicines, vaccines and technologies (medical products); (5) health financing; and (6) leadership and governance. For example, the health workforce means having enough health workers with the right skills, who are well trained, motivated, fairly paid and distributed across the country (including rural areas) so that services reach everyone.', null, '[{"point": "Six WHO building blocks: service delivery; health workforce; health information systems; access to essential medicines (medical products, vaccines, technologies); financing; leadership/ governance", "marks": 2}, {"point": "Correct 2-3 line description of any one (e.g. health workforce: enough, well-trained, motivated and fairly distributed staff)", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
