  values ('ME', 'short_answer', 'What is EEG? Briefly describe the different types of brain waves. (1+2 marks)', 'An EEG (electroencephalogram) is a recording of the electrical activity of the brain, picked up by small electrodes placed on the scalp; it is used to diagnose epilepsy and seizures, study sleep and assess brain function (for example in encephalopathy or brain death). Types of brain waves: delta waves (below 4 Hz) - slow, large waves seen in deep sleep and in infants; theta waves (4-7 Hz) - in drowsiness and light sleep and in children; alpha waves (8-13 Hz) - in a relaxed, awake person with eyes closed, best over the back of the head; beta waves (13-30 Hz) - fast, low waves when alert, thinking or anxious; and gamma waves (above 30 Hz) - linked to high-level processing and concentration.', null, '[{"point": "EEG (electroencephalogram/ -graphy): a recording of the electrical activity of the brain using electrodes placed on the scalp; used for epilepsy, sleep studies, brain death, encephalopathy", "marks": 1}, {"point": "Brain waves: delta (<4 Hz, deep sleep, infants), theta (4-7 Hz, drowsiness/ light sleep, children), alpha (8-13 Hz, relaxed awake with eyes closed), beta (13-30 Hz, alert, active thinking), gamma (>30 Hz, high-level processing)", "marks": 2}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'medical-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
    324, 'historical_official', 'awaiting_review',
