  values ('ME', 'short_answer', 'What is oxygen debt? (3 marks)', 'Oxygen debt (excess post-exercise oxygen consumption) is the extra amount of oxygen the body takes in after strenuous exercise, over and above its normal resting need. During heavy exercise the muscles need more oxygen than the lungs and blood can supply, so they also respire anaerobically: glucose is broken down to lactic acid, and stores of ATP, creatine phosphate and oxygen bound to myoglobin are used up. After the exercise stops, the person keeps breathing deeply and the heart keeps beating fast; the extra oxygen ''repays the debt'' by oxidising lactic acid or converting it back to glucose in the liver (Cori cycle), rebuilding ATP and creatine phosphate, re-oxygenating myoglobin and haemoglobin and cooling the body.', null, '[{"point": "Definition: the extra oxygen taken in after strenuous exercise, above the resting need (excess post-exercise oxygen consumption, EPOC)", "marks": 1}, {"point": "Cause: during heavy exercise oxygen supply is not enough, so muscles respire anaerobically, producing lactic acid and using up ATP, creatine phosphate and myoglobin oxygen", "marks": 1}, {"point": "Repayment: the extra oxygen is used to oxidise lactic acid (or convert it to glucose in the liver), restore ATP/ creatine phosphate and reoxygenate myoglobin and blood; hence heavy breathing and fast heart rate continue after exercise", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'medical-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
