  values ('ME', 'short_answer', 'What is the difference between renewable and non-renewable energy? Name 2 sources of each. (1+2 marks)', 'Renewable energy comes from natural sources that are constantly replaced and will not run out in human terms, and is generally cleaner; non-renewable energy comes from sources found in limited amounts that took millions of years to form and will be used up, and burning them pollutes. Renewable sources: hydropower (Bhutan''s main source), solar energy, wind, biomass and geothermal energy. Non-renewable sources: coal, petroleum (oil and diesel), natural gas and nuclear fuel (uranium).', null, '[{"point": "Renewable energy comes from sources that are naturally replenished and will not run out (in human time); non-renewable comes from limited sources that take millions of years to form and are used up", "marks": 1}, {"point": "Renewable: hydropower, solar, wind, biomass, geothermal; non-renewable: coal, petroleum/ oil, natural gas, nuclear (uranium)", "marks": 2}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
